def order_jobs(deps):
    """Return a topological ordering of jobs and their prerequisites.

    Every job named in ``deps`` (as a key or as a prerequisite) appears exactly
    once, with each prerequisite listed before the job that depends on it.
    Ties among runnable jobs are broken by lexicographic order.  A cycle in
    the dependency graph raises ``ValueError``.

    The input mapping and its iterables are never modified.
    """
    # Copy prerequisites into a set-based adjacency structure without
    # touching the caller's data.  Duplicate prerequisites are collapsed.
    prerequisites = {}
    for job, deps_iter in deps.items():
        prerequisites.setdefault(job, set()).update(deps_iter)

    # Prerequisites that are not keys of `deps` are jobs with no prerequisites.
    for job in list(prerequisites):
        for prereq in prerequisites[job]:
            if prereq not in prerequisites:
                prerequisites[prereq] = set()

    # Kahn's algorithm, always emitting the lexicographically smallest
    # currently runnable job.
    remaining = {job: set(prereqs) for job, prereqs in prerequisites.items()}
    dependents = {job: [] for job in prerequisites}
    for job, prereqs in prerequisites.items():
        for prereq in prereqs:
            dependents[prereq].append(job)

    ready = sorted(job for job, prereqs in remaining.items() if not prereqs)
    order = []

    while ready:
        job = ready.pop(0)
        order.append(job)
        newly_ready = []
        for dependent in dependents[job]:
            remaining[dependent].discard(job)
            if not remaining[dependent] and dependent not in order:
                newly_ready.append(dependent)
        if newly_ready:
            ready.extend(newly_ready)
            ready.sort()

    if len(order) != len(prerequisites):
        raise ValueError("dependency cycle detected")

    return order
